spec.setup_code:
var geometry = new api.THREE.BoxGeometry(0.5, 0.5, 0.5);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                var speed = 1.5;
                var range = 2;
                return {
                  update: function(t) {
                    var seconds = t * 0.001;
                    var raw = (seconds * speed) % (range * 2);
                    cube.position.x = raw <= range ? -range + raw : range - (raw - range);
                  }
                };

var speedPxPerSec = 90;
                return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var seconds = t * 0.001;
                    var margin = 30;
                    var travel = W - margin * 2;
                    var cycleTime = travel / speedPxPerSec;
                    var phase = (seconds % (cycleTime * 2)) / cycleTime;
                    var frac = phase <= 1 ? phase : 2 - phase;
                    var x = margin + frac * travel;
                    var y = H / 2;
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 16, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.strokeStyle = '#999';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(margin, y);
                    ctx.lineTo(W - margin, y);
                    ctx.stroke();
                    ctx.fillStyle = '#333';
                    ctx.font = '12px sans-serif';
                    ctx.fillText('constant speed = equal distance per second', margin, y - 30);
                  }
                };
